INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wrap', 'v.', '/ræp/', '包;裹;缠绕', 'In spring the mountains are wrapped in shining silver water.', '春天,群山被波光粼粼的银色水面所环绕。', 'At One with Nature', 1, 0, 'senior', 'wordlist', 'required1', 'U6', 'be wrapped in', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sheet', 'n.', '/ʃiːt/', '(冰、水等的)一大片;薄片;床单', 'In winter the terraces are covered in sheets of white frost.', '冬天,梯田被大片大片的白霜覆盖。', 'At One with Nature', 2, 0, 'senior', 'wordlist', 'required1', 'U6', 'a sheet of frost', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'frost', 'n.', '/frɒst/', '霜;严寒天气', 'White frost forms on the rice fields on cold winter mornings.', '寒冷的冬日清晨,稻田上结起白霜。', 'At One with Nature', 3, 0, 'senior', 'wordlist', 'required1', 'U6', 'white frost', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'terrace', 'n.', '/ˈterɪs/', '梯田;露台', 'The local people turned the whole mountain into rice terraces.', '当地人把整座山变成了水稻梯田。', 'At One with Nature', 4, 0, 'senior', 'wordlist', 'required1', 'U6', 'rice terraces', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'dynasty', 'n.', '/ˈdɪnəsti/', '朝代;王朝', 'Work on the terraces began in the Yuan Dynasty.', '梯田的修建始于元朝。', 'At One with Nature', 5, 0, 'senior', 'wordlist', 'required1', 'U6', 'the Yuan Dynasty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'completion', 'n.', '/kəmˈpliːʃ(ə)n/', '完成;结束', 'The work continued for hundreds of years until its completion.', '这项工程持续了几百年直到完成。', 'At One with Nature', 6, 0, 'senior', 'wordlist', 'required1', 'U6', 'until its completion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'region', 'n.', '/ˈriːdʒ(ə)n/', '地区;区域', 'There are few large, flat areas of land in this region.', '这个地区几乎没有大片平坦的土地。', 'At One with Nature', 7, 0, 'senior', 'wordlist', 'required1', 'U6', 'in the region', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'therefore', 'adv.', '/ˈðeəfɔː/', '因此;由此', 'The land was steep, and the people therefore built terraces.', '土地陡峭,因此人们修建了梯田。', 'At One with Nature', 8, 0, 'senior', 'wordlist', 'required1', 'U6', 'and therefore', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'steep', 'adj.', '/stiːp/', '陡的;陡峭的', 'The mountains here are steep and the soil is shallow.', '这里的山很陡,土层也很浅。', 'At One with Nature', 9, 0, 'senior', 'wordlist', 'required1', 'U6', 'steep mountains', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'soil', 'n.', '/sɔɪl/', '土壤;泥土', 'The flat terraces stop the thin soil from being washed away.', '平整的梯田防止薄薄的土壤被冲走。', 'At One with Nature', 10, 0, 'senior', 'wordlist', 'required1', 'U6', 'shallow soil', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shallow', 'adj.', '/ˈʃæləʊ/', '浅的', 'Because the soil is shallow, crops are hard to grow on the slopes.', '因为土层浅,庄稼很难在山坡上生长。', 'At One with Nature', 11, 0, 'senior', 'wordlist', 'required1', 'U6', 'shallow soil', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'prevent', 'v.', '/prɪˈvent/', '阻止;防止', 'The terraces catch the rain and prevent the soil from washing away.', '梯田蓄住雨水,防止土壤被冲走。', 'At One with Nature', 12, 0, 'senior', 'wordlist', 'required1', 'U6', 'prevent ... from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'harmony', 'n.', '/ˈhɑːməni/', '和谐;融洽相处', 'The farmers have worked in harmony with nature for centuries.', '几百年来,农民们一直与自然和谐相处。', 'At One with Nature', 13, 0, 'senior', 'wordlist', 'required1', 'U6', 'in harmony with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'design', 'v.', '/dɪˈzaɪn/', '设计;构思', 'The terraces are cleverly designed with hundreds of waterways.', '梯田设计精巧,有数百条相连的水道。', 'At One with Nature', 14, 0, 'senior', 'wordlist', 'required1', 'U6', 'cleverly designed', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'vapour', 'n.', '/ˈveɪpə/', '蒸气;水汽', 'The sun heats the water and turns it into vapour.', '太阳加热水分,把它变成水汽。', 'At One with Nature', 15, 0, 'senior', 'wordlist', 'required1', 'U6', 'turn into vapour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'harm', 'v.', '/hɑːm/', '伤害;损害', 'Fish in the terraces eat insects that can harm the rice.', '梯田里的鱼吃掉会损害水稻的害虫。', 'At One with Nature', 16, 0, 'senior', 'wordlist', 'required1', 'U6', 'harm the crops', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'crop', 'n.', '/krɒp/', '庄稼;作物;收成', 'Modern technology could help the village grow more crops.', '现代技术能帮助村庄种出更多庄稼。', 'At One with Nature', 17, 0, 'senior', 'wordlist', 'required1', 'U6', 'grow crops', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'agriculture', 'n.', '/ˈæɡrɪˌkʌltʃə/', '农业', 'New generations still use ancient methods of agriculture.', '新一代人仍在使用古老的农耕方法。', 'At One with Nature', 18, 0, 'senior', 'wordlist', 'required1', 'U6', 'ancient agriculture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'replace', 'v.', '/rɪˈpleɪs/', '取代;替换;更换', 'Some people want to replace chemical dyes with natural ones.', '有些人想用天然染料替换化学染料。', 'At One with Nature', 19, 0, 'senior', 'wordlist', 'required1', 'U6', 'replace ... with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'material', 'n.', '/məˈtɪəriəl/', '材料;原料', 'The materials for making natural dyes come from plants.', '制作天然染料的原料来自植物。', 'At One with Nature', 20, 0, 'senior', 'wordlist', 'required1', 'U6', 'natural materials', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mineral', 'n.', '/ˈmɪn(ə)rəl/', '矿物;矿产', 'Some natural dyes are made from minerals found in the ground.', '有些天然染料由地里的矿物制成。', 'At One with Nature', 21, 0, 'senior', 'wordlist', 'required1', 'U6', 'mineral compounds', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'consumer', 'n.', '/kənˈsjuːmə/', '消费者;顾客', 'Natural dyes are popular with consumers who care about nature.', '天然染料受到关心自然的消费者的欢迎。', 'At One with Nature', 22, 0, 'senior', 'wordlist', 'required1', 'U6', 'green consumers', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'priority', 'n.', '/praɪˈɒrɪti/', '优先处理的事;当务之急', 'For these buyers, caring for the environment is a priority.', '对这些买家来说,保护环境是头等大事。', 'At One with Nature', 23, 0, 'senior', 'wordlist', 'required1', 'U6', 'a top priority', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'beauty', 'n.', '/ˈbjuːti/', '美;美丽;美的事物', 'Using natural dyes reminds us of the beauty of nature.', '使用天然染料让我们想起自然之美。', 'At One with Nature', 24, 0, 'senior', 'wordlist', 'required1', 'U6', 'natural beauty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'barrier', 'n.', '/ˈbæriə/', '障碍;屏障;壁垒', 'The Great Barrier Reef lies off the coast of Australia.', '大堡礁位于澳大利亚海岸外。', 'At One with Nature', 25, 0, 'senior', 'wordlist', 'required1', 'U6', 'the Great Barrier Reef', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reef', 'n.', '/riːf/', '礁;暗礁;珊瑚礁', 'The reef is the biggest structure made by living things.', '这片礁石是由生物造出的最大结构。', 'At One with Nature', 26, 0, 'senior', 'wordlist', 'required1', 'U6', 'a coral reef', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'structure', 'n.', '/ˈstrʌktʃə/', '结构;构造;建筑物', 'This natural structure is home to many sea creatures.', '这一天然结构是许多海洋生物的家园。', 'At One with Nature', 27, 0, 'senior', 'wordlist', 'required1', 'U6', 'a huge structure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'living', 'adj.', '/ˈlɪvɪŋ/', '活的;活着的', 'The reef was built by tiny living organisms in the sea.', '这片礁石是由海中微小的活生物建造的。', 'At One with Nature', 28, 0, 'senior', 'wordlist', 'required1', 'U6', 'living organisms', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'organism', 'n.', '/ˈɔːɡənɪz(ə)m/', '生物;有机体', 'Millions of small organisms live together on the reef.', '数百万微小生物共同生活在礁石上。', 'At One with Nature', 29, 0, 'senior', 'wordlist', 'required1', 'U6', 'living organisms', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'basin', 'n.', '/ˈbeɪs(ə)n/', '盆地;低洼地', 'The Turpan Basin is famous for its sweet grapes.', '吐鲁番盆地以其甜美的葡萄而闻名。', 'At One with Nature', 30, 0, 'senior', 'wordlist', 'required1', 'U6', 'the Turpan Basin', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'grand', 'adj.', '/ɡrænd/', '宏伟的;壮丽的', 'The Grand Canyon is a truly grand natural wonder.', '大峡谷是一处真正壮丽的自然奇观。', 'At One with Nature', 31, 0, 'senior', 'wordlist', 'required1', 'U6', 'the Grand Canyon', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'canyon', 'n.', '/ˈkænjən/', '峡谷', 'The canyon is a valley almost two kilometres deep.', '这条峡谷是一道近两千米深的山谷。', 'At One with Nature', 32, 0, 'senior', 'wordlist', 'required1', 'U6', 'a deep canyon', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'valley', 'n.', '/ˈvæli/', '山谷;溪谷', 'A great river slowly cut this deep valley out of the rock.', '一条大河慢慢在岩石中切出了这道深谷。', 'At One with Nature', 33, 0, 'senior', 'wordlist', 'required1', 'U6', 'a deep valley', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'narrow', 'adj.', '/ˈnærəʊ/', '狭窄的;狭的', 'Tourists stand on a narrow glass platform to see the canyon.', '游客站在狭窄的玻璃平台上观看峡谷。', 'At One with Nature', 34, 0, 'senior', 'wordlist', 'required1', 'U6', 'a narrow platform', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'platform', 'n.', '/ˈplætfɔːm/', '平台;高台', 'The glass platform lets visitors look straight down the cliff.', '玻璃平台让游客可以直直地俯视悬崖。', 'At One with Nature', 35, 0, 'senior', 'wordlist', 'required1', 'U6', 'a glass platform', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'waterfall', 'n.', '/ˈwɔːtəfɔːl/', '瀑布', 'Huangguoshu is most famous for its huge waterfall.', '黄果树最出名的就是它巨大的瀑布。', 'At One with Nature', 36, 0, 'senior', 'wordlist', 'required1', 'U6', 'a great waterfall', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'thunder', 'v.', '/ˈθʌndə/', '打雷;轰鸣', 'Local people call the falls ''the smoke that thunders''.', '当地人把这瀑布称作“会打雷的烟雾”。', 'At One with Nature', 37, 0, 'senior', 'wordlist', 'required1', 'U6', 'the smoke that thunders', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'channel', 'n.', '/ˈtʃænl/', '海峡;水道;频道', 'The English Channel separates England from France.', '英吉利海峡把英格兰与法国分开。', 'At One with Nature', 38, 0, 'senior', 'wordlist', 'required1', 'U6', 'the English Channel', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tunnel', 'n.', '/ˈtʌnl/', '隧道;地道', 'The two countries are joined by a long rail tunnel.', '这两个国家由一条长长的铁路隧道相连。', 'At One with Nature', 39, 0, 'senior', 'wordlist', 'required1', 'U6', 'a rail tunnel', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'camel', 'n.', '/ˈkæm(ə)l/', '骆驼', 'We rode camels, the famous ''ships of the desert''.', '我们骑着骆驼,那著名的“沙漠之舟”。', 'At One with Nature', 40, 0, 'senior', 'wordlist', 'required1', 'U6', 'ride camels', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'desert', 'n.', '/ˈdezət/', '沙漠;荒漠', 'Crossing the desert felt like sailing on an ocean of sand.', '穿越沙漠就像在沙海上航行。', 'At One with Nature', 41, 0, 'senior', 'wordlist', 'required1', 'U6', 'an ocean of desert', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sail', 'v.', '/seɪl/', '(乘船)航行;启航', 'It felt as if I would sail on an endless ocean of sand.', '感觉就像我要在无尽的沙海上航行。', 'At One with Nature', 42, 0, 'senior', 'wordlist', 'required1', 'U6', 'sail on', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'climate', 'n.', '/ˈklaɪmɪt/', '气候', 'Different living things thrive in different climate zones.', '不同的生物在不同的气候带繁衍生息。', 'At One with Nature', 43, 0, 'senior', 'wordlist', 'required1', 'U6', 'climate zones', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'publish', 'v.', '/ˈpʌblɪʃ/', '出版;发表', 'The book The Secret Garden was first published in 1911.', '《秘密花园》一书于1911年首次出版。', 'At One with Nature', 44, 0, 'senior', 'wordlist', 'required1', 'U6', 'first published', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'expert', 'adj./n.', '/ˈekspɜːt/', '内行的;熟练的;专家', 'Expert gardeners know just the right corner for roses.', '内行的园丁知道哪个角落最适合种玫瑰。', 'At One with Nature', 45, 0, 'senior', 'wordlist', 'required1', 'U6', 'expert gardeners', '美音 /ˈekspɜːrt/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'branch', 'n.', '/brɑːntʃ/', '树枝;分支;分公司', 'Some people just sit under the branches and enjoy nature.', '有些人只是坐在树枝下,享受大自然。', 'At One with Nature', 46, 0, 'senior', 'wordlist', 'required1', 'U6', 'under the branches', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rent', 'v.', '/rent/', '租用;租借', 'People without a garden can rent a small piece of land.', '没有花园的人可以租一小块地。', 'At One with Nature', 47, 0, 'senior', 'wordlist', 'required1', 'U6', 'rent a piece of land', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rooftop', 'n.', '/ˈruːftɒp/', '屋顶', 'One idea is to turn rooftops into private green gardens.', '一个想法是把屋顶变成私人绿色花园。', 'At One with Nature', 48, 0, 'senior', 'wordlist', 'required1', 'U6', 'rooftop gardens', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'limited', 'adj.', '/ˈlɪmɪtɪd/', '有限的;受限的', 'In cities, limited space leads people to look for new ideas.', '在城市里,有限的空间促使人们寻找新办法。', 'At One with Nature', 49, 0, 'senior', 'wordlist', 'required1', 'U6', 'limited space', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'benefit', 'n.', '/ˈbenɪfɪt/', '好处;益处', 'Herbal tea has many health benefits for the body.', '花草茶对身体有许多健康益处。', 'At One with Nature', 50, 0, 'senior', 'wordlist', 'required1', 'U6', 'health benefits', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u6.01', '①介词 + which / whom(in which / for whom)', 'A2', 10, '外研社版必修第一册 U6 — 关系代词指物用 which、指人用 whom;介词由从句中的动词或名词搭配决定(grow rice in / learn from / depend on / home to)。指人时介词后只能 whom,指物时只能 which。', 1, 'required1', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u6.02', '②非限制性定语从句(逗号 + which / who / whose)', 'A2', 10, '外研社版必修第一册 U6 — 逗号隔开、对先行词作补充说明:指物用 which、指人用 who、所属用 whose;非限制性定从中绝不可用 that。', 2, 'required1', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u6.03', '③which 指代整个主句(…, which means …)', 'A2', 10, '外研社版必修第一册 U6 — 逗号后的 which 指代前面整句话的内容、在从句中作主语;此处只能用 which,that / what / it / this 都不能引导这类从句。', 3, 'required1', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The terraces created flat areas ____ the local people could grow rice.', 'in which', 'in whom', 'for which', 'for whom', 'A', 'grow rice in areas、先行词指物 → 介词 in + which。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'He was an expert ____ the Zhuang people learnt a great deal about farming.', 'from which', 'from whom', 'to whom', 'to which', 'B', 'learn a great deal from sb、先行词指人 → from + whom。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'These terraces still mean a lot to the local people ____ old traditions hold much value.', 'for which', 'by whom', 'for whom', 'by which', 'C', 'traditions hold value for sb、先行词指人 → for + whom。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The sun warms the water and forms clouds ____ rain falls onto the terraces again.', 'from whom', 'on which', 'on whom', 'from which', 'D', 'rain falls from clouds、先行词指物 → from + which。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The Zhuang and Yao are the people ____ this mountain region has long been home.', 'to whom', 'to which', 'for whom', 'for which', 'A', 'the region is home to sb、先行词指人 → to + whom。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'Farmers admire the clever way ____ people work in harmony with nature.', 'on which', 'in which', 'in whom', 'on whom', 'B', 'the way in which 是固定结构、先行词指物 → in + which。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'She has kind neighbours ____ she shares the rice harvest every autumn.', 'with which', 'to whom', 'with whom', 'to which', 'C', 'share sth with sb、先行词指人 → with + whom。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The reef is a giant structure ____ many sea creatures depend for food and shelter.', 'on whom', 'for which', 'for whom', 'on which', 'D', 'depend on sth、先行词指物 → on + which。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'Climate change is a serious problem ____ many scientists are deeply worried.', 'about which', 'about whom', 'with which', 'with whom', 'A', 'be worried about sth、先行词指物 → about + which。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'Guides look after the visitors ____ they prepare a safe path up the steep hill.', 'for which', 'for whom', 'with whom', 'with which', 'B', 'prepare sth for sb、先行词指人 → for + whom。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The Turpan Basin is the region ____ the sweetest grapes in China are grown.', 'in whom', 'by which', 'in which', 'by whom', 'C', 'grapes are grown in the region、先行词指物 → in + which。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The young farmers respect the elders ____ they have learnt the ancient methods.', 'from which', 'to whom', 'to which', 'from whom', 'D', 'learn sth from sb、先行词指人 → from + whom。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'Those without a garden can rent small pieces of land ____ they grow vegetables.', 'on which', 'on whom', 'for which', 'for whom', 'A', 'grow things on the land、先行词指物 → on + which。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The walls of the drying houses have many holes ____ the desert wind can pass.', 'through whom', 'through which', 'by which', 'by whom', 'B', 'wind passes through holes、先行词指物 → through + which。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The Inuit are the northern people ____ the frozen Arctic has always been home.', 'to which', 'in whom', 'to whom', 'in which', 'C', 'the Arctic is home to sb、先行词指人 → to + whom。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The Arctic is one of the few cold zones ____ very few plants can survive.', 'in whom', 'of which', 'of whom', 'in which', 'D', 'survive in the zones、先行词指物 → in + which。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'We warmly thanked the local guide ____ we explored the deep, narrow valley.', 'with whom', 'with which', 'from whom', 'from which', 'A', 'explore with sb、先行词指人 → with + whom。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The huge waterfall is the very feature ____ Huangguoshu National Park is famous.', 'for whom', 'for which', 'by which', 'by whom', 'B', 'be famous for sth、先行词指物 → for + which。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The Channel Tunnel is a long rail tunnel, most ____ runs deep under the sea.', 'of whom', 'in which', 'of which', 'in whom', 'C', 'most of the tunnel、先行词指物 → of + which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.01'), 'The children listened to the old farmer ____ they heard the story of the terraces.', 'from which', 'to whom', 'to which', 'from whom', 'D', 'hear sth from sb、先行词指人 → from + whom。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The Longji Rice Terraces, ____ were built over many centuries, attract thousands of visitors.', 'which', 'that', 'who', 'where', 'A', '非限制性定从、先行词指物、逗号后不可用 that → which。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The Zhuang people, ____ have farmed these mountains for generations, live close to nature.', 'which', 'who', 'that', 'whom', 'B', '非限制性定从、先行词指人作主语 → who。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The Great Barrier Reef, ____ lies off the coast of Australia, is the largest living structure.', 'that', 'who', 'which', 'when', 'C', '非限制性定从、先行词指物、不可用 that → which。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'We met an old farmer, ____ family has kept the terraces for hundreds of years.', 'who', 'which', 'that', 'whose', 'D', '后面跟名词 family、表所属 → whose。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'Natural dyes, ____ people make from plants and minerals, are becoming popular again.', 'which', 'that', 'who', 'what', 'A', '非限制性定从、先行词指物作宾语、不可用 that → which。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'Emma, ____ is now travelling in Guizhou, sent a video of a huge waterfall.', 'which', 'who', 'whom', 'that', 'B', '非限制性定从、先行词指人作主语 → who。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The Grand Canyon, ____ is almost two kilometres deep, is a truly grand sight.', 'that', 'where', 'which', 'who', 'C', '非限制性定从、先行词指物、不可用 that → which。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'Victoria Falls, ____ local name means ''the smoke that thunders'', lie between two countries.', 'which', 'that', 'who', 'whose', 'D', '后面跟名词 name、表所属(物亦可用 whose)→ whose。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'My grandfather, ____ loves gardening, spends every Sunday among his flowers.', 'who', 'which', 'whom', 'that', 'A', '非限制性定从、先行词指人作主语 → who。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The Channel Tunnel, ____ runs under the sea, joins England and France by rail.', 'that', 'which', 'who', 'where', 'B', '非限制性定从、先行词指物、不可用 that → which。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'Herbal tea, ____ many British people drink to relax, has several health benefits.', 'that', 'who', 'which', 'what', 'C', '非限制性定从、先行词指物作宾语、不可用 that → which。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The Inuit, ____ live in the frozen Arctic, eat a lot of fish and meat.', 'which', 'that', 'whom', 'who', 'D', '非限制性定从、先行词指人作主语 → who。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The author of The Secret Garden, ____ book was published in 1911, loved nature.', 'whose', 'who', 'which', 'that', 'A', '后面跟名词 book、表所属 → whose。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The Turpan Basin, ____ is famous for its sweet grapes, lies in Xinjiang.', 'that', 'which', 'where', 'who', 'B', '非限制性定从、先行词指物、不可用 that → which。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'Mrs Green, ____ has turned her rooftop into a beautiful garden, lives next door.', 'which', 'that', 'who', 'whom', 'C', '非限制性定从、先行词指人作主语 → who。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'Rooftop gardens, ____ help to clean the city air, are a clever modern idea.', 'that', 'who', 'what', 'which', 'D', '非限制性定从、先行词指物、不可用 that → which。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The local people, ____ traditions hold much value, still farm in the old way.', 'whose', 'who', 'which', 'that', 'A', '后面跟名词 traditions、表所属 → whose。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The camel, ____ people call ''the ship of the desert'', crosses dry sand with ease.', 'that', 'which', 'who', 'whom', 'B', '非限制性定从、先行词指物(动物)作宾语、不可用 that → which。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'Expert gardeners, ____ know just the right corner for roses, win many prizes.', 'which', 'that', 'who', 'whom', 'C', '非限制性定从、先行词指人作主语 → who。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.02'), 'The deep valley, ____ was slowly cut by a great river, draws many tourists.', 'that', 'where', 'who', 'which', 'D', '非限制性定从、先行词指物、不可用 that → which。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.03'), 'The knowledge is passed down through families, ____ means new generations keep the old methods.', 'which', 'that', 'what', 'it', 'A', '指代前面整句话、作从句主语 → which。', 2, 1, 'mcq');
