INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.03'), 'Tourism brings more money to the region, ____ also harms the local environment.', 'that', 'what', 'it', 'which', 'D', 'which 指代前面整句 → which。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.03'), 'The sun heats the water and turns it into vapour, ____ later forms clouds above.', 'which', 'that', 'it', 'this', 'A', 'which 指代整句、作主语 → which。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U6' AND code='f1u6.03'), 'Many people now grow plants on their walls, ____ surprises visitors to the city.', 'that', 'which', 'what', 'it', 'B', 'which 指代前面整句 → which。', 2, 14, 'mcq');
