INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Longji Rice Terraces', 'High in the mountains of Guangxi lie the Longji Rice Terraces, built long ago by the local Zhuang and Yao people. Work on them began in the Yuan Dynasty and went on for hundreds of years. Because there was little flat land in the region, the people cut the steep mountains into terraces so that they could grow more rice. The mountains here also have plenty of rain, but the soil is thin. The flat terraces hold the rainwater and stop the soil from washing away. Most clever of all is the way the farmers work in harmony with nature. Hundreds of waterways connect the terraces, carrying rain down the slopes. The sun then turns the water into vapour, which rises and forms clouds, and the rain falls once more. Birds and fish live here too, and some of them eat the insects that would harm the rice.', '说明·梯田与自然和谐', 148, '[{"q":"Why did the local people build terraces on the mountains?","answer":"A","options":["To gain more land for growing rice.","To stop visitors from climbing up.","To store water for the city below.","To keep their animals safe at night."],"explanation":"原文''little flat land… so that they could grow more rice''的转述。"},{"q":"How do the flat terraces help with the thin soil?","answer":"B","options":["They add chemicals to the soil.","They hold the rain and keep the soil from being washed off.","They make the mountains less steep over time.","They bring soil down from the mountain top."],"explanation":"原文''hold the rainwater and stop the soil from washing away''的转述。"},{"q":"What part do the birds and fish play on the terraces?","answer":"A","options":["They eat insects that could damage the rice.","They carry water between the fields.","They turn the water into vapour.","They build new waterways each year."],"explanation":"末句''eat the insects that would harm the rice''的转述。"}]'::jsonb, '[{"word":"terrace","cn":"梯田"},{"word":"soil","cn":"土壤"},{"word":"harmony","cn":"和谐"},{"word":"vapour","cn":"水汽"}]'::jsonb, 2, 'required1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Colours from Nature', 'Among the many gifts that nature gives us are natural dyes, the colours used to brighten cloth and other materials. The most common source of these dyes is plants, but they can also come from insects, sea creatures and minerals found in the ground. For thousands of years, people coloured their clothes in this way, until cheaper chemical dyes slowly replaced them. Today, however, natural dyes are returning to popularity, which pleases many artists and craftspeople. They say the colours are brighter and last far longer than chemical ones. Natural dyes are also growing more popular with shoppers for whom caring for the environment is a top priority. Such buyers know that these colours do little harm to rivers and soil. By choosing dyes made from plants and minerals, people feel they can remind themselves of the beauty of the natural world and help to protect it at the same time.', '说明·天然染料', 151, '[{"q":"Where do most natural dyes come from?","answer":"B","options":["Only from sea creatures.","Mainly from plants.","Mostly from factories.","Only from minerals."],"explanation":"原文''The most common source… is plants''的转述。"},{"q":"Why did natural dyes become less common in the past?","answer":"C","options":["People stopped wearing coloured cloth.","Plants became too rare to use.","Cheaper chemical dyes took their place.","The colours were thought to be ugly."],"explanation":"原文''cheaper chemical dyes slowly replaced them''的转述。"},{"q":"What do shoppers who care about the environment believe about natural dyes?","answer":"D","options":["They cost almost nothing to make.","They are the only colours left.","They fade more quickly than others.","They cause little damage to nature."],"explanation":"原文''do little harm to rivers and soil''的转述。"}]'::jsonb, '[{"word":"dye","cn":"染料"},{"word":"material","cn":"材料"},{"word":"mineral","cn":"矿物"},{"word":"consumer","cn":"消费者"}]'::jsonb, 2, 'required1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Great Barrier Reef', 'Off the coast of Australia lies the Great Barrier Reef, the largest structure on Earth ever made by living things. It is not the work of people but of countless tiny sea organisms that have lived and grown together for millions of years. Slowly, their hard remains built up into a huge wall of colour that now stretches for over two thousand kilometres. The reef is home to a great variety of fish, turtles and other creatures, which makes it one of the richest places for life in all the oceans. Visitors can explore it by boat or even from an underwater observatory, where they watch the busy world below without getting wet. Sadly, warmer seas and dirty water now put the reef in danger. Many scientists are deeply worried about its future, and people everywhere are being asked to help keep this natural wonder alive for those who come after us.', '说明·大堡礁', 152, '[{"q":"What makes the Great Barrier Reef special among structures on Earth?","answer":"A","options":["It is the biggest one built by living creatures.","It was built by ancient people.","It is made completely of stone.","It is the oldest building in Australia."],"explanation":"原文''the largest structure… ever made by living things''的转述。"},{"q":"Why is the reef one of the richest places for life?","answer":"B","options":["It is warmer than any other sea.","Many kinds of sea creatures live there.","No people are ever allowed to visit.","It has no fish at all."],"explanation":"原文''home to a great variety of fish, turtles and other creatures''的转述。"},{"q":"What threatens the reef today?","answer":"C","options":["Too many underwater observatories.","A lack of tiny organisms.","Warmer and dirtier seawater.","Boats that are too slow."],"explanation":"原文''warmer seas and dirty water now put the reef in danger''的转述。"}]'::jsonb, '[{"word":"reef","cn":"礁"},{"word":"structure","cn":"结构"},{"word":"organism","cn":"生物"},{"word":"living","cn":"活的"}]'::jsonb, 2, 'required1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Wonders Shaped by Nature', 'All over the world there are amazing places that nature alone has shaped. In the United States, the Grand Canyon is a valley almost two kilometres deep, slowly cut out of the rock by a great river over millions of years. Brave visitors can stand on a narrow glass platform and look straight down. In Africa, Victoria Falls is the largest waterfall in the world. The water drops with such force that the local people call it ''the smoke that thunders'', a name which fits it perfectly. Between England and France lies the English Channel, a stretch of sea that long kept the two countries apart. Today they are joined by the Channel Tunnel, a rail tunnel about fifty kilometres long, most of which runs deep under the sea. Each of these places reminds us how powerful and beautiful the natural world can be, and how small we sometimes are beside it.', '说明·世界地理奇观', 152, '[{"q":"How was the Grand Canyon formed?","answer":"D","options":["People dug it out for farming.","It was built as a tourist platform.","A great storm created it in one night.","A river slowly cut it from the rock."],"explanation":"原文''slowly cut out of the rock by a great river''的转述。"},{"q":"Why do local people call Victoria Falls ''the smoke that thunders''?","answer":"A","options":["Because the falling water is so loud and powerful.","Because smoke really rises from a fire there.","Because it is hidden inside a tunnel.","Because it is the smallest waterfall on Earth."],"explanation":"原文''drops with such force… the smoke that thunders''的转述。"},{"q":"What is true about the Channel Tunnel?","answer":"B","options":["It floats on top of the sea.","Much of it lies far below the sea.","It separates England from France.","It is only a few metres long."],"explanation":"原文''about fifty kilometres long, most of which runs deep under the sea''的转述。"}]'::jsonb, '[{"word":"canyon","cn":"峡谷"},{"word":"platform","cn":"平台"},{"word":"waterfall","cn":"瀑布"},{"word":"channel","cn":"海峡"}]'::jsonb, 2, 'required1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Life in the Frozen North', 'Far in the north, in the cold lands of the Arctic, live the Inuit, a people for whom ice and snow have always been home. Around four million people live in the Arctic region, and about one hundred and seventy thousand of them are Inuit. Their world is one of the few climate zones where almost nothing will grow, so they once depended mostly on fish and meat. Eating such food keeps their bodies strong enough to face the freezing weather. In the past, many lived in houses of snow called igloos, which stay surprisingly warm inside. For part of the year the sun never rises, and this long polar night gives families more time to spend together, though it can also feel rather lonely. Today tourism brings money and new jobs to the region, which is welcome news. Yet it also brings crowds and rubbish, and the Inuit worry that their quiet, clean environment is slowly being harmed.', '说明·北极因纽特人生活', 159, '[{"q":"Why did the Inuit once depend mainly on fish and meat?","answer":"C","options":["They disliked the taste of vegetables.","Fish and meat were cheaper to buy.","Almost no crops can grow in their cold land.","Their doctors told them to."],"explanation":"原文''one of the few climate zones where almost nothing will grow''的转述。"},{"q":"What is one good thing about the long polar night?","answer":"D","options":["It makes plants grow faster.","It keeps tourists away all year.","It warms up the igloos.","It gives families more time together."],"explanation":"原文''gives families more time to spend together''的转述。"},{"q":"Why are the Inuit worried about tourism?","answer":"A","options":["It may be harming their clean environment.","It brings too little money.","It makes the winters colder.","It stops them from eating fish."],"explanation":"原文''their quiet, clean environment is slowly being harmed''的转述。"}]'::jsonb, '[{"word":"climate","cn":"气候"},{"word":"region","cn":"地区"},{"word":"harm","cn":"损害"},{"word":"benefit","cn":"好处"}]'::jsonb, 2, 'required1', 'U6', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Nation of Gardeners', 'People in Britain love their gardens. About half of them spend their free time gardening, and many proudly say they have ''green fingers''. A hundred years ago, only the very rich owned gardens, but soon homes with small gardens began to be built for ordinary families too. Each spring, children plant sunflowers and wait to see whose grows the tallest, while expert gardeners look for the perfect corner for their roses. Some people enter their vegetables in competitions; others are happy just to sit under the branches of a tree and enjoy the world around them. In crowded cities, however, space is limited. People without a garden can rent a small piece of land on which to grow things, and thousands in London are waiting for such a piece. One newer idea is to turn rooftops and walls into private gardens, which has helped make the cities greener and the air cleaner for everyone.', '说明·英国人爱园艺', 154, '[{"q":"What was true about gardens in Britain a hundred years ago?","answer":"B","options":["Every family owned a large one.","Only wealthy people had them.","They were found only on rooftops.","Nobody was interested in them."],"explanation":"原文''only the very rich owned gardens''的转述。"},{"q":"What can city people without a garden do to grow plants?","answer":"C","options":["Move out to the countryside.","Give up gardening completely.","Rent a little plot of ground nearby.","Plant only inside their homes."],"explanation":"原文''rent a small piece of land on which to grow things''的转述。"},{"q":"How have rooftop and wall gardens helped the cities?","answer":"D","options":["They have made land more expensive.","They have removed all the trees.","They have stopped people gardening.","They have made cities greener with cleaner air."],"explanation":"原文''helped make the cities greener and the air cleaner''的转述。"}]'::jsonb, '[{"word":"expert","cn":"内行的"},{"word":"branch","cn":"树枝"},{"word":"rent","cn":"租用"},{"word":"rooftop","cn":"屋顶"}]'::jsonb, 2, 'required1', 'U6', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U6', 'Camels and Grapes in Turpan', 'Last summer my family travelled to Xinjiang, a place I had always wanted to (1)____. We spent three days in the Turpan (2)____, which is famous for its sweet grapes. The weather was hot and dry, and the land looked like a huge (3)____ of golden sand. One afternoon we rode (4)____, the animals that people call ''the ships of the desert''. Sitting up so high, I felt as if I were going to (5)____ across an ocean of sand. Our guide showed us the special houses (6)____ grapes are dried into raisins. The walls have many small holes that let the wind (7)____ through. In this clever way the grapes lose their water but keep their sweet (8)____. On our last evening, we watched the sun go down over the (9)____, and everything turned a soft gold. I will never (10)____ that wonderful trip.', 145, 2, '[{"q":"1","answer":"A","options":["visit","sell","build","drop"],"explanation":"wanted to visit 想去游览。"},{"q":"2","answer":"B","options":["Forest","Basin","Island","Harbour"],"explanation":"the Turpan Basin 吐鲁番盆地。"},{"q":"3","answer":"C","options":["garden","lake","desert","city"],"explanation":"a huge desert of sand 一片沙漠。"},{"q":"4","answer":"D","options":["birds","fish","sheep","camels"],"explanation":"rode camels、''ships of the desert'' 指骆驼。"},{"q":"5","answer":"A","options":["sail","sleep","sing","cook"],"explanation":"sail across an ocean of sand 在沙海上航行。"},{"q":"6","answer":"B","options":["who","where","when","why"],"explanation":"the houses where grapes are dried 地点先行词用 where。"},{"q":"7","answer":"C","options":["stop","fall","pass","sink"],"explanation":"let the wind pass through 让风穿过。"},{"q":"8","answer":"D","options":["price","noise","weight","flavour"],"explanation":"keep their sweet flavour 保持甜味。"},{"q":"9","answer":"A","options":["sand","snow","sea","grass"],"explanation":"the sun went down over the sand 沙漠上。"},{"q":"10","answer":"B","options":["sell","forget","lose","build"],"explanation":"never forget the trip 永远不会忘记。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U6', 'Tea from Our Own Garden', 'My grandmother grows her own little tea garden, (1)____ she plants easy herbs such as mint and lemongrass. She says home-grown tea is a pleasant (2)____ from ordinary tea. Fruit and herbal teas come in many lovely (3)____ and tastes. Some are made from lemon and ginger, while others use the (4)____ and leaves from the garden. Grandma firmly believes that herbal tea has real health (5)____. When I feel tired, she gives me a warm cup to bring back my (6)____. If I cannot (7)____ well at night, she chooses a tea that helps me relax. A cup of mint tea is also good for the (8)____ after a big meal. Best of all, growing and drinking our own tea costs very (9)____ and brings the whole family (10)____. I have come to love these quiet afternoons spent with her.', 141, 2, '[{"q":"1","answer":"C","options":["who","when","where","why"],"explanation":"the garden where she plants herbs 地点先行词用 where。"},{"q":"2","answer":"D","options":["price","noise","error","change"],"explanation":"a pleasant change from ordinary tea 一种变化。"},{"q":"3","answer":"A","options":["colours","prices","mistakes","machines"],"explanation":"many lovely colours and tastes 颜色。"},{"q":"4","answer":"B","options":["cars","flowers","coins","clocks"],"explanation":"the flowers and leaves from the garden 花。"},{"q":"5","answer":"C","options":["problems","mistakes","benefits","prices"],"explanation":"health benefits 健康益处。"},{"q":"6","answer":"D","options":["homework","luggage","furniture","energy"],"explanation":"bring back my energy 恢复精力。"},{"q":"7","answer":"A","options":["sleep","swim","sing","cook"],"explanation":"cannot sleep well at night 入睡。"},{"q":"8","answer":"B","options":["garden","stomach","window","street"],"explanation":"good for the stomach 有益肠胃。"},{"q":"9","answer":"C","options":["many","few","little","tall"],"explanation":"costs very little 花费很少(不可数)。"},{"q":"10","answer":"D","options":["alone","apart","away","together"],"explanation":"brings the family together 把家人聚到一起。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U6', 'Our School Rooftop Garden', 'Our school had an empty (1)____ that almost no one ever used. Last year our teacher had a clever (2)____: why not turn it into a garden? Space on the ground was (3)____, so the roof was the perfect place. First we carried up bags of soil and (4)____ vegetables and flowers in large wooden boxes. We had to (5)____ them every morning before class began. Slowly, green leaves started to (6)____, and soon the grey roof was full of (7)____. The garden does far more than just look pretty. The plants help to clean the city (8)____ and keep the building cool in summer. Working up there also teaches us to (9)____ nature and to care for living things. Now the rooftop is the (10)____ place in the whole school, and teachers from other schools have come to see what we made.', 143, 2, '[{"q":"1","answer":"A","options":["rooftop","ticket","river","forest"],"explanation":"an empty rooftop 屋顶。"},{"q":"2","answer":"B","options":["price","idea","noise","song"],"explanation":"a clever idea 一个好主意。"},{"q":"3","answer":"C","options":["free","wide","limited","open"],"explanation":"space was limited 空间有限。"},{"q":"4","answer":"D","options":["sold","threw","lost","planted"],"explanation":"planted vegetables and flowers 种植。"},{"q":"5","answer":"A","options":["water","sell","hide","break"],"explanation":"water them every morning 浇水。"},{"q":"6","answer":"B","options":["disappear","appear","fall","sink"],"explanation":"leaves started to appear 开始长出。"},{"q":"7","answer":"C","options":["noise","dust","life","smoke"],"explanation":"full of life 充满生机。"},{"q":"8","answer":"D","options":["money","paper","glass","air"],"explanation":"clean the city air 净化空气。"},{"q":"9","answer":"A","options":["respect","forget","waste","harm"],"explanation":"respect nature 尊重自然。"},{"q":"10","answer":"B","options":["worst","favourite","emptiest","coldest"],"explanation":"the favourite place 最受欢迎的地方。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U6', 'A Walk to the Waterfall', 'On our trip to Guizhou, we walked through a green (1)____ to reach the famous Huangguoshu (2)____. Long before we could see it, we could (3)____ a deep, thundering sound far ahead. Then the water came into (4)____, falling from a great height into a deep pool (5)____. Clouds of fine (6)____ rose into the air and gently touched our faces like rain. Our guide told us that it is the largest waterfall in the whole (7)____. We stood on a narrow (8)____ and looked straight down, holding tightly to the rail. The sight was both a little frightening and truly (9)____. I took many photos, but none of them could really (10)____ how powerful the falling water was. Standing there, I felt how small one person is beside such a wonder of nature.', 134, 2, '[{"q":"1","answer":"C","options":["desert","island","valley","city"],"explanation":"a green valley 山谷。"},{"q":"2","answer":"D","options":["garden","market","station","waterfall"],"explanation":"Huangguoshu Waterfall 瀑布。"},{"q":"3","answer":"A","options":["hear","eat","buy","read"],"explanation":"could hear a sound 听到声音。"},{"q":"4","answer":"B","options":["price","view","box","word"],"explanation":"come into view 进入视野。"},{"q":"5","answer":"C","options":["above","inside","below","behind"],"explanation":"into a deep pool below 下方的水潭。"},{"q":"6","answer":"D","options":["sand","snow","stone","vapour"],"explanation":"clouds of fine vapour 水汽。"},{"q":"7","answer":"A","options":["world","room","garden","school"],"explanation":"the largest waterfall in the world 世界上。"},{"q":"8","answer":"B","options":["kitchen","platform","library","bedroom"],"explanation":"a narrow platform 平台。"},{"q":"9","answer":"C","options":["boring","silent","wonderful","empty"],"explanation":"frightening and wonderful 美妙。"},{"q":"10","answer":"D","options":["sell","hide","lose","show"],"explanation":"could not show how powerful 展现。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U6', 'The World Beneath the Sea', 'Beneath the warm, blue sea lies a hidden world that is full of (1)____. Coral may look like stone, but it is really made of millions of tiny living (2)____. Over a very long (3)____, they grow together and slowly build great walls under the water. These walls become a (4)____ for fish, turtles and many other sea creatures. Some people like to explore this quiet world by (5)____, while others watch it from an underwater room without ever getting (6)____. Sadly, warmer water and (7)____ seas now put many of these places in great (8)____. If we are not careful, this beautiful underwater world could one day (9)____ for ever. That is why more and more people are working hard to (10)____ the life that lives beneath the waves.', 130, 2, '[{"q":"1","answer":"A","options":["colour","noise","dust","smoke"],"explanation":"full of colour 充满色彩。"},{"q":"2","answer":"B","options":["machines","things","houses","cars"],"explanation":"tiny living things 微小生物。"},{"q":"3","answer":"C","options":["money","space","time","noise"],"explanation":"over a very long time 很长时间。"},{"q":"4","answer":"D","options":["price","war","rule","home"],"explanation":"become a home for fish 家园。"},{"q":"5","answer":"A","options":["boat","train","plane","bus"],"explanation":"explore the sea by boat 乘船。"},{"q":"6","answer":"B","options":["rich","wet","late","tall"],"explanation":"without getting wet 弄湿。"},{"q":"7","answer":"C","options":["clean","empty","dirty","quiet"],"explanation":"warmer water and dirty seas 受污染。"},{"q":"8","answer":"D","options":["order","fashion","colour","danger"],"explanation":"put ... in great danger 危险。"},{"q":"9","answer":"A","options":["disappear","appear","arrive","return"],"explanation":"could disappear for ever 消失。"},{"q":"10","answer":"B","options":["harm","protect","sell","forget"],"explanation":"work hard to protect the life 保护。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U6', 'Greening Our Neighbourhood', 'In our neighbourhood there used to be an ugly piece of waste (1)____ that was full of rubbish. One spring, a group of us decided to (2)____ it. First we cleared away all the rubbish, and then we (3)____ young trees and bright flowers. It was hard (4)____, and our hands soon grew tired and dirty. But week by week, the little plants began to (5)____ taller and stronger. Birds and butterflies came to (6)____ the new green space. Old people now sit there under the (7)____ to rest, while children run and play on the soft grass. Our little garden also helps to make the (8)____ cleaner for everyone living nearby. I have learnt that even one small group can bring (9)____ back into a busy city. Best of all, the whole neighbourhood now feels much more like a (10)____.', 141, 2, '[{"q":"1","answer":"C","options":["sky","river","ground","wall"],"explanation":"waste ground 荒地。"},{"q":"2","answer":"D","options":["sell","buy","leave","change"],"explanation":"decided to change it 改造它。"},{"q":"3","answer":"A","options":["planted","sold","ate","lost"],"explanation":"planted young trees 种下。"},{"q":"4","answer":"B","options":["news","work","music","water"],"explanation":"hard work 辛苦的活儿。"},{"q":"5","answer":"C","options":["fall","sink","grow","stop"],"explanation":"began to grow taller 长高。"},{"q":"6","answer":"D","options":["sell","build","cook","visit"],"explanation":"came to visit the green space 光临。"},{"q":"7","answer":"A","options":["branches","windows","doors","roofs"],"explanation":"sit under the branches 树枝下。"},{"q":"8","answer":"B","options":["floor","air","glass","metal"],"explanation":"make the air cleaner 空气。"},{"q":"9","answer":"C","options":["money","noise","nature","traffic"],"explanation":"bring nature back 把自然带回。"},{"q":"10","answer":"D","options":["factory","market","prison","family"],"explanation":"feels more like a family 像一家人。"}]'::jsonb, 6, 'fltrp');
