INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 Life in the Arctic', '外研社版必修第一册 U6 · passage', 2, 'The Inuit live in the cold, frozen lands of the Arctic.
