INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U6 听力·短文 The Grand Canyon', '外研社版必修第一册 U6 · passage', 2, 'The Grand Canyon is a huge valley in the United States.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Description of a Natural Wonder(写一处自然奇观的介绍)', 'A Place Where People and Nature Live as One', '假设你叫李华,你的英国朋友 Jane 想了解中国的自然景观。请用英语写一篇约80词的短文,介绍一处你喜欢的自然奇观(如龙脊梯田、黄果树瀑布等),内容包括:① 它在哪里、有什么特点;② 当地人如何与自然和谐相处或如何保护它;③ 你的感受。注意:恰当使用本单元的定语从句(介词+which/whom、非限制性定从、which 指代整句)。', 'Suppose you are Li Hua. Your British friend Jane wants to learn about China''s natural wonders. Write a short passage (about 80 words) introducing a natural wonder you like (e.g. the Longji Rice Terraces or Huangguoshu Waterfall), including: 1) where it is and what is special about it; 2) how local people live in harmony with it or protect it; 3) your own feelings. Try to use this unit''s attributive clauses naturally.', '["介绍地点与特点(… is a wonder that lies in …)","人与自然和谐 / 保护(The local people, who … , work in harmony with nature.)","用本单元定从(the way in which … / …, which means …)","表达感受(Standing there, I felt …)"]'::jsonb, 70, 100, 'Hi Jane! Let me tell you about the Longji Rice Terraces, a wonder that lies high in the mountains of Guangxi. They were built long ago by the local Zhuang and Yao people, for whom these mountains have always been home. There is little flat land in the region, so the people cut the steep slopes into terraces in which they could grow rice. The way in which they work in harmony with nature is truly clever. Standing there, I felt how wisely people and nature can live as one.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["The Longji Rice Terraces are a wonder that lies high in the mountains of Guangxi.","They were built by the local people, for whom these mountains have always been home.","The people cut the steep slopes into terraces in which they could grow rice.","The way in which they work in harmony with nature is truly clever."]'::jsonb, '[{"wrong":"the people who these mountains are home","correct":"the people for whom these mountains are home","note":"be home to sb,介词 for/to + whom,关系代词前要带介词。"},{"wrong":"terraces which they could grow rice in them","correct":"terraces in which they could grow rice","note":"介词提前到关系代词前,从句里不再重复 in them。"},{"wrong":"They work in harmony with nature, that means a lot.","correct":"They work in harmony with nature, which means a lot.","note":"指代前面整句、引导非限制性定从只能用 which,不用 that。"}]'::jsonb, '【自然奇观介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U6', '{"title":"定语从句3·介词+关系代词 / 非限制性定从 / which 指代整句 速查","intro":"本单元三招:① 介词 + which(物)/ whom(人),介词由从句里的搭配决定;② 逗号引导的非限制性定从,补充说明、绝不用 that;③ 逗号后的 which 可以指代前面整个主句。","table":{"headers":["结构","用法 / 例句"],"rows":[["介词 + which","指物:the areas in which they grow rice;the clouds from which rain falls"],["介词 + whom","指人:the people for whom traditions hold value;the expert from whom we learnt"],["逗号 + which / who / whose","非限制性:The reef, which lies off Australia, …;The Zhuang, who farm here, …"],["逗号 + which(指整句)","This is passed down, which means new generations keep the old ways."]]},"specialRules":[{"rule":"介词放关系代词前时,指人只能 whom、指物只能 which(不能用 who/that)","mark":"for whom √ / for who × / in which √ / in that ×"},{"rule":"非限制性定语从句(有逗号)里绝不能用 that","mark":"The terraces, which …, √ / The terraces, that …, ×"},{"rule":"介词由从句里的动词/名词搭配决定","mark":"grow rice in → in which;depend on → on which;learn from → from whom"},{"rule":"逗号后的 which 可指代前面一整句话,在从句作主语","mark":"…, which means / which helps / which makes …"}],"why":["介词提到关系代词前是更正式的书面写法:the way in which = the way that = the way(省略);从句里就不再重复介词。","非限制性定从只是''顺便补充一句'',去掉后主句意思仍完整,所以用逗号,而 that 不能引导这种从句。"],"gaokaoPoints":["介词 + which / whom 的选择(看从句搭配 + 先行词指人还是指物),语法填空与改错高频。","非限制性定从中 which / who / whose 的判断,以及''逗号后不可用 that''。","which 指代整个主句(…, which means …),常出现在读后续写与高级句中。"],"examVsReal":[{"exam":"the people for whom the land is home（考试/正式）","real":"the people the land is home to","note":"正式书面把介词提前;日常口语常把介词留在句末、省略关系词"},{"exam":"the holes through which the wind passes（考试)","real":"the holes the wind passes through","note":"口语更爱说 the holes (that) the wind passes through"}]}'::jsonb, 'fltrp');
